"""Co-index of the octahedral tower: verify coind(S^n) = n by explicit maps."""
from __future__ import annotations
from itertools import product
from typing import List, Tuple, Callable

OctVertex = Tuple[int, int]

def oct_vertices(n: int) -> List[OctVertex]:
    return [(i, s) for i in range(n + 1) for s in (+1, -1)]

def oct_anti(v: OctVertex) -> OctVertex:
    i, s = v
    return (i, -s)

def is_equivariant_simplicial(verts: List, anti_src: Callable, anti_tgt: Callable, f: Callable) -> bool:
    for v in verts:
        if f(anti_src(v)) != anti_tgt(f(v)):
            return False
    for p in verts:
        for q in verts:
            if f(p) == anti_tgt(f(q)) and p != anti_src(q):
                return False
    return True

def any_gmap_oct(m: int, n: int) -> bool:
    """Exhaustive existence check for an equivariant simplicial map S^m -> S^n."""
    targets = oct_vertices(n)
    for choice in product(targets, repeat=m + 1):
        table = {}
        for i in range(m + 1):
            table[(i, +1)] = choice[i]
            table[(i, -1)] = oct_anti(choice[i])
        f = lambda v, t=table: t[v]
        if is_equivariant_simplicial(oct_vertices(m), oct_anti, oct_anti, f):
            return True
    return False

def coind_oct(n: int) -> int:
    # Lower bound: axis inclusion (i,s)->(i,s) works for every m <= n.
    best = max(m for m in range(n + 1)
               if is_equivariant_simplicial(oct_vertices(m), oct_anti, oct_anti, lambda v: v))
    # Upper bound (Borsuk-Ulam): no equivariant map S^{n+1} -> S^n.
    assert not any_gmap_oct(n + 1, n)
    return best

if __name__ == "__main__":
    for n in range(3):
        print(f"coind(S^{n}) = {coind_oct(n)}")

"""Coordinate-splitting isomorphism S^m * S^n = S^(m+n+1): verify bijection + equivariance."""
from __future__ import annotations
from typing import List, Tuple, Callable

OctVertex = Tuple[int, int]
JoinVertex = Tuple[str, OctVertex]

def oct_vertices(n: int) -> List[OctVertex]:
    return [(i, s) for i in range(n + 1) for s in (+1, -1)]

def oct_anti(v): 
    i, s = v; return (i, -s)

def join_vertices(m: int, n: int) -> List[JoinVertex]:
    return [("L", v) for v in oct_vertices(m)] + [("R", v) for v in oct_vertices(n)]

def join_anti(v: JoinVertex) -> JoinVertex:
    tag, (i, s) = v
    return (tag, (i, -s))

def phi(m: int, n: int) -> Callable[[JoinVertex], OctVertex]:
    def f(v):
        tag, (i, s) = v
        return (i, s) if tag == "L" else (m + 1 + i, s)
    return f

def psi(m: int, n: int) -> Callable[[OctVertex], JoinVertex]:
    def g(v):
        k, s = v
        return ("L", (k, s)) if k <= m else ("R", (k - (m + 1), s))
    return g

def verify(m: int, n: int) -> bool:
    src, tgt = join_vertices(m, n), oct_vertices(m + n + 1)
    F, G = phi(m, n), psi(m, n)
    bijection = sorted(F(v) for v in src) == sorted(tgt)
    round_trips = all(G(F(v)) == v for v in src) and all(F(G(w)) == w for w in tgt)
    equivariant = all(F(join_anti(v)) == oct_anti(F(v)) for v in src)
    return bijection and round_trips and equivariant

if __name__ == "__main__":
    for m, n in [(0, 0), (1, 1), (2, 3)]:
        print(f"S^{m} * S^{n} = S^{m+n+1}: {verify(m, n)}")

"""Constructive lower bound: build an explicit equivariant map S^(a+b+1) -> K * L."""
from __future__ import annotations
from typing import List, Tuple, Callable

OctVertex = Tuple[int, int]
JoinVertex = Tuple[str, OctVertex]

def oct_vertices(n: int) -> List[OctVertex]:
    return [(i, s) for i in range(n + 1) for s in (+1, -1)]

def oct_anti(v): 
    i, s = v; return (i, -s)

def join_anti(v: JoinVertex) -> JoinVertex:
    tag, u = v; return (tag, oct_anti(u))

def is_equivariant_simplicial(verts, anti_src, anti_tgt, f) -> bool:
    if any(f(anti_src(v)) != anti_tgt(f(v)) for v in verts):
        return False
    for p in verts:
        for q in verts:
            if f(p) == anti_tgt(f(q)) and p != anti_src(q):
                return False
    return True

def witness(a: int, b: int, F: Callable, G: Callable) -> Callable[[OctVertex], JoinVertex]:
    """(F * G) composed with the split isomorphism inverse of S^(a+b+1)."""
    def H(v):
        k, s = v
        if k <= a:
            return ("L", F((k, s)))
        return ("R", G((k - (a + 1), s)))
    return H

if __name__ == "__main__":
    a, b = 1, 2
    ident = lambda v: v          # F: S^a -> S^a, G: S^b -> S^b
    H = witness(a, b, ident, ident)
    ok = is_equivariant_simplicial(oct_vertices(a + b + 1), oct_anti, join_anti, H)
    print(f"S^{a+b+1} -> S^{a} * S^{b} equivariant simplicial: {ok}")
    print(f"coind(S^{a} * S^{b}) >= {a + b + 1}")

