from typing import Tuple, Callable

OctVertex = Tuple[int, int]
JoinVertex = Tuple[str, OctVertex]

def split_forward(m: int, n: int) -> Callable[[JoinVertex], OctVertex]:
    """S^m * S^n -> S^{m+n+1}: concatenate axes, keep signs. O(1) per vertex."""
    def phi(v: JoinVertex) -> OctVertex:
        tag, (i, s) = v
        return (i, s) if tag == "L" else (m + 1 + i, s)
    return phi

def split_inverse(m: int, n: int) -> Callable[[OctVertex], JoinVertex]:
    """S^{m+n+1} -> S^m * S^n: split the axis index at threshold m+1. O(1) per vertex."""
    def psi(v: OctVertex) -> JoinVertex:
        k, s = v
        return ("L", (k, s)) if k <= m else ("R", (k - (m + 1), s))
    return psi
